Ltac nodisj := repeat match goal with H : _ \/ _ |- _ => clear H end.
Ltac dlia := first [ solve [ L5FastLia.prune_arith; nodisj; L5FastLia.lia_ne ]
                   | solve [ L5FastLia.prune_arith; match goal with H : _ \/ _ |- _ => L5SAR.clear_disj_but H; destruct H; L5FastLia.lia_ne end ]
                   | solve [ L5FastLia.prune_arith; nodisj; L5FastLia.lia_st ]
                   | solve [ L5FastLia.prune_arith; match goal with H : _ \/ _ |- _ => L5SAR.clear_disj_but H; destruct H; L5FastLia.lia_st end ] ].
Local Ltac lia := dlia.
Module PEBEQE.
Ltac sassum := match goal with |- ?G => match goal with H : ?T |- _ => constr_eq T G; exact H end end.
Ltac inl := apply L5K.In_of_mem; vm_compute; reflexivity.
Abbreviation reg i := (Z_to_bv 5 (Z.of_nat i)).
Abbreviation RSEGS := AsanUbsan.M.loaded_segments.
Abbreviation AD := PeCLayoutB.CADDR_B.
Abbreviation EE := PeCLayoutB.EADDR_B.
Abbreviation st fx R pc M := (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)).

Section Stage.
Context {SCFG_P : ScfgP}.
Variables (L : asan_layout) (ar : asan_run) (C : asan_statics_cells) (HI : asan_iface).
Hypothesis LY : PMB.layout L C.
Hypothesis HIok : HAJ.asan_iface_okR L ar C SCFG HI.
Hypothesis EXT : HAJ.asan_ext_ok L ar SCFG HI PMB.EXT.
Let LYa := PMB.ly_as0 L C LY.

Theorem empty : PMSPA.opnew_spec RSEGS AD L ar HI -> forall (fx : FPState) R M model K LBX FF LK Aw cr ov fb b stk d sp r pk pl kd ln,
    ri_inv HI (PEC.enc_own (PEC.ENC b 0 stk d) ++ LBX) FF LK cr Aw M (vml_of model) -> L5CA.amodel_ok Aw model -> K [] ->
    PMSPA.entryA AD L ar R M sp r 0 ->
    getr R (reg 10) = Z_to_bv 64 (ov + 24) -> PMSPA.aobjA FF ov 56 -> ov mod 8 = 0 ->
    PECA.enc_atA RSEGS EE L ar M ov fb (PEC.ENC b 0 stk d) ->
    PMSTA.base_okA RSEGS AD M ->
    getr R (reg 11) = Z_to_bv 64 pk -> getr R (reg 12) = Z_to_bv 64 pl -> pk mod 4 = 0 -> pl mod 8 = 0 -> byte_at M (S pk) 0 -> byte_at M (S pl) 0 ->
    PMBEK.argp (ar_sptop ar) FF sp (ov + 32) pk 4 -> PMBEK.argp (ar_sptop ar) FF sp (ov + 32) pl 8 -> (pk + 4 <= ov \/ ov + 56 <= pk) -> (pl + 8 <= ov \/ ov + 56 <= pl) ->
    L5.u32_at RSEGS M pk kd -> L5.u64_at RSEGS M pl ln -> 0 <= kd <= 3 -> 0 <= ln <= UbjRef.MAX_ITEMS -> acredit_ok L cr 24 ->
    (forall (fx' : FPState) R' M' model' LK' Aw' B, regs_preserved R R' -> PECA.enc_atA RSEGS EE L ar M' ov fb (PEC.ENC B 1 (stk ++ [EI kd ln 0]) d) ->
        PMSTA.base_okA RSEGS AD M' -> L5CA.ahpres L ar LBX FF sp (PMSPA.pm_scr 0) [(ov + 24, 24)] M M' ->
        model_rt model model' -> incl LK' LK -> incl Aw Aw' -> L5CA.amodel_ok Aw' model' ->
        ri_inv HI (PEC.enc_own (PEC.ENC B 1 (stk ++ [EI kd ln 0]) d) ++ LBX) FF LK' (adebit L cr 24) Aw' M' (vml_of model') ->
        getr R' (reg 10) = Z_to_bv 64 (B + PEC.ESZ * Z.of_nat (length stk) + PEC.ESZ) ->
        srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx' R' r M' model') K) ->
    srealizes RSEGS SCFG (@PMSPA.cfg RSEGS fx R 0xb0648 M model) K.
Proof.
